fn main() {
    let words = ["rotor", "banana", "level", "quiet", "deified", "system", "civic"];
    let mut palindromes = 0;
    for &word in words.iter() {
        println!("{}", word);
        println!("{}", word.len());
        let reversed: String = word.chars().rev().collect();
        println!("{}", reversed);
        if word == reversed {
            println!("true");
            palindromes += 1;
        } else {
            println!("false");
        }
        let vowels = "aeiou";
        let vowel_count = word.chars().filter(|&c| vowels.contains(c)).count();
        println!("{}", vowel_count);
        let unique_chars: std::collections::HashSet<char> = word.chars().collect();
        println!("{}", unique_chars.len());
    }
    println!("{}", palindromes);
}

fn main() {
    let north = [("bolt", 40, 3), ("hinge", 8, 25), ("plate", 15, 12)];
    let south = [
        ("clamp", 6, 45),
        ("rod", 22, 9),
        ("washer", 100, 1),
        ("gasket", 4, 30),
    ];
    fn print_warehouse(name: &str, parts: &[(&str, i32, i32)]) {
        let total_value = parts.iter().map(|(_, q, p)| q * p).sum::<i32>();
        let below_ten_count = parts.iter().filter(|(_, q, _)| *q < 10).count();
        let max_value_part = parts
            .iter()
            .max_by_key(|(_, _, p)| p)
            .map_or("", |(name, _, _)| name);
        println!("{}", name);
        println!("{}", total_value);
        println!("{}", below_ten_count);
        println!("{}", max_value_part);
    }
    print_warehouse("North", &north);
    print_warehouse("South", &south);
    let north_total = north.iter().map(|(_, q, p)| q * p).sum::<i32>();
    let south_total = south.iter().map(|(_, q, p)| q * p).sum::<i32>();
    if north_total > south_total {
        println!("North");
    } else {
        println!("South");
    }
}

fn main() {
    let numbers = [360, 97, 1024, 561, 143, 2003];
    let mut prime_count = 0;
    for &num in &numbers {
        println!("{}", num);
        let (distinct_primes, sum, largest) = find_distinct_primes(num);
        println!("{}", distinct_primes.len());
        println!("{}", sum);
        println!("{}", largest);
        if is_prime(num) {
            println!("true");
            prime_count += 1;
        } else {
            println!("false");
        }
    }
    println!("{}", prime_count);
}
fn find_distinct_primes(mut num: u64) -> (Vec<u64>, u64, u64) {
    let mut distinct_primes = Vec::new();
    let mut sum = 0;
    let mut largest = 0;
    for i in 2..=num {
        while num % i == 0 {
            if !distinct_primes.contains(&i) {
                distinct_primes.push(i);
                sum += i;
                largest = i;
            }
            num /= i;
        }
    }
    (distinct_primes, sum, largest)
}
fn is_prime(num: u64) -> bool {
    if num <= 1 {
        return false;
    }
    for i in 2..=((num as f64).sqrt() as u64) {
        if num % i == 0 {
            return false;
        }
    }
    true
}

